import {MOTIONS,BUILTIN_SOUNDS,cleanEffect,resolvedMotion,motionFrames} from './effects-model.js';
import {createAudioEngine,unlockAudio,audioContext} from './audio-engine.js';
import {editPCM} from './audio-tools.js';
import {birdFlight} from './core.js';
export function setupEffects({words,meaningOf,artwork,isReduced=()=>false,onConfigChange=()=>{}}){
 const $=id=>document.getElementById(id);let saved={};try{saved=JSON.parse(localStorage.getItem('kotoba-effects-v1'))||{};}catch{}
 let current='',draft=cleanEffect(),previewAnimation=null,previewSound=null,previewTimer=0,editBuffer=null,editName='',editPlay=null,recorder=null,stream=null,recordTimer=0,clockTimer=0,recordStarted=0,recordPending=false,recordGeneration=0;
 const say=s=>{$('effectMessage').textContent=s;},audio=createAudioEngine({onError:say});
 const get=(word)=>cleanEffect(saved[word],meaningOf(word));
 function stopPreview(){previewAnimation?.cancel();previewAnimation=null;previewSound?.stop();previewSound=null;clearTimeout(previewTimer);editPlay?.stop();editPlay=null;$('effectSprite').style.transform='';}
 function fields(){draft=cleanEffect({motion:$('effectMotion').value,duration:$('effectDuration').value,amplitude:$('effectAmplitude').value,cycles:$('effectCycles').value,sound:$('effectSound').value,playMode:$('effectPlayMode').value,volume:Number($('effectVolume').value)/100},meaningOf(current));return draft;}
 function fill(){for(const [id,key]of [['effectMotion','motion'],['effectDuration','duration'],['effectAmplitude','amplitude'],['effectCycles','cycles'],['effectSound','sound'],['effectPlayMode','playMode']])$(id).value=draft[key];$('effectVolume').value=Math.round(draft.volume*100);$('effectVolumeValue').textContent=Math.round(draft.volume*100)+'%';}
 function soundOptions(value=draft.sound){const el=$('effectSound');el.replaceChildren();const add=(value,name,parent=el)=>{const o=document.createElement('option');o.value=value;o.textContent=name;parent.append(o);};add('none','効果音なし');const group=document.createElement('optgroup');group.label='用意した音（合成音）';el.append(group);for(const [id,name]of BUILTIN_SOUNDS)add('builtin:'+id,name,group);if(audio.library.size){const custom=document.createElement('optgroup');custom.label='追加・録音・工房の音';el.append(custom);for(const item of audio.library.values())add('audio:'+item.id,item.name,custom);}if([...el.options].some(o=>o.value===value))el.value=value;else{add(value,'保存音を読み込み中');el.value=value;}}
 function preview(){
  stopPreview();const c=fields();fill();const kind=resolvedMotion(c,meaningOf(current)),sprite=$('effectSprite'),stage=$('effectStage');sprite.innerHTML=artwork(current);$('effectMotionDescription').textContent=MOTIONS.find(m=>m[0]===c.motion)?.[2]||'';$('effectVolumeValue').textContent=Math.round(c.volume*100)+'%';stage.classList.toggle('preview-road',kind==='road');
  const gentle=isReduced()||matchMedia('(prefers-reduced-motion: reduce)').matches,seconds=kind==='none'||gentle?0:c.duration;let frames;
  if(seconds){if(kind==='fly'){const sw=stage.clientWidth,sh=stage.clientHeight,start={x:sw/2,y:sh/2},flight=birdFlight(start,{minX:52,maxX:sw-52,minY:52,maxY:sh-52});frames=flight.points.map(p=>({transform:`translate(${p.x-start.x}px,${p.y-start.y}px)`}));}
   else if(kind==='road'){const d=Math.min(stage.clientWidth*.3,95);frames=[{transform:'translate(0,0)'},{transform:`translate(${d}px,0)`},{transform:`translate(${d}px,-42px)`},{transform:`translate(${d}px,0)`},{transform:'translate(0,0)'}];}
   else frames=motionFrames(kind,82,82,c.amplitude,c.cycles);
   previewAnimation=sprite.animate(frames,{duration:seconds*1000,easing:kind==='fly'?'linear':'ease-in-out'});
  }
  previewSound=audio.play('preview',c.sound,{loop:c.playMode==='loop'&&seconds>0,volume:c.volume});previewTimer=setTimeout(()=>{previewSound?.motionEnd();$('effectPreviewState').textContent='動きのプレビュー終了';},seconds*1000||500);$('effectPreviewState').textContent=seconds?'プレビュー中':'動きなし';
 }
 async function open(word){audio.stopAll();stopPreview();current=word||words()[0];const select=$('effectWord');select.replaceChildren();for(const w of words()){const o=document.createElement('option');o.value=o.textContent=w;select.append(o);}select.value=current;draft=get(current);soundOptions();fill();$('effectSprite').innerHTML=artwork(current);$('effectMotionDescription').textContent=MOTIONS.find(m=>m[0]===draft.motion)?.[2]||'';$('effectPreviewState').textContent='動きを選ぶとプレビューします';$('effectEditor').hidden=true;say('選んだ動きはすぐにプレビューします。変更は「この絵の設定を保存」で確定します。');$('recordState').textContent='';$('effectDialog').showModal();await audio.ready;soundOptions(draft.sound);}
 $('manageEffects').onclick=()=>{$('adultDialog').close();open();};
 $('effectWord').onchange=()=>{finishRecording(true);stopPreview();current=$('effectWord').value;draft=get(current);soundOptions();fill();$('effectEditor').hidden=true;preview();};
 $('effectMotion').innerHTML=MOTIONS.map(([key,name])=>`<option value="${key}">${name}</option>`).join('');
 for(const id of ['effectMotion','effectDuration','effectAmplitude','effectCycles','effectSound','effectPlayMode'])$(id).onchange=()=>{preview();if(id==='effectSound')$('effectEditor').hidden=true;};
 $('effectVolume').oninput=()=>{$('effectVolumeValue').textContent=$('effectVolume').value+'%';};$('effectVolume').onchange=preview;
 $('effectPreview').onclick=preview;$('effectStop').onclick=()=>{stopPreview();audio.stopAll();$('effectPreviewState').textContent='停止';};
 $('effectSave').onclick=()=>{fields();fill();const before=saved[current];saved[current]={...draft};try{localStorage.setItem('kotoba-effects-v1',JSON.stringify(saved));onConfigChange();say(`「${current}」の動きと効果音を保存しました。`);}catch{if(before)saved[current]=before;else delete saved[current];say('設定を保存できませんでした。');}};
 function drawWave(){const cv=$('soundWave'),ctx=cv.getContext('2d'),w=cv.width,h=cv.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#edf1e4';ctx.fillRect(0,0,w,h);if(!editBuffer)return;const start=+$('soundStart').value,end=+$('soundEnd').value;ctx.fillStyle='#cee0bd';ctx.fillRect(start/editBuffer.duration*w,0,(end-start)/editBuffer.duration*w,h);const data=editBuffer.getChannelData(0);ctx.strokeStyle='#52745a';ctx.beginPath();for(let x=0;x<w;x++){const from=Math.floor(x/w*data.length),to=Math.max(from+1,Math.floor((x+1)/w*data.length));let peak=0;for(let i=from;i<to;i++)peak=Math.max(peak,Math.abs(data[i]));ctx.moveTo(x,h/2-peak*h*.45);ctx.lineTo(x,h/2+peak*h*.45);}ctx.stroke();}
 function showEditor(buffer,name){editBuffer=buffer;editName=name;$('soundName').value=name;$('soundStart').value=0;$('soundEnd').value=Math.min(buffer.duration,60).toFixed(2);$('soundStart').max=$('soundEnd').max=buffer.duration.toFixed(2);$('soundLength').textContent=`元の音：${buffer.duration.toFixed(2)}秒（保存する範囲は60秒まで）`;$('effectEditor').hidden=false;drawWave();}
 async function importBlob(blob,name,guard=()=>true){stopPreview();if(blob.size>25*1024*1024)throw Error('音声ファイルは25MB以内で選んでください。');const c=audioContext(),buffer=await c.decodeAudioData(await blob.arrayBuffer());if(buffer.duration<.02)throw Error('音声が短すぎます。');if(!guard()||!$('effectDialog').open)return;showEditor(buffer,name);say('波形を見ながら使う範囲を指定できます。');}
 $('soundFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{await importBlob(file,file.name.replace(/\.[^.]+$/,''));}catch(e){say(e.message||'音声を開けませんでした。このブラウザで再生できる形式を選んでください。');}e.target.value='';};
 $('editSelectedSound').onclick=async()=>{try{if(fields().sound==='none'){say('編集する音を選んでください。');return;}await unlockAudio();const buffer=await audio.getBuffer(draft.sound);showEditor(buffer,$('effectSound').selectedOptions[0].textContent);}catch(e){say(e.message);}};
 for(const id of ['soundStart','soundEnd'])$(id).oninput=drawWave;
 function edited(){if(!editBuffer)throw Error('編集する音を読み込んでください。');const start=Number($('soundStart').value),end=Number($('soundEnd').value);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end>editBuffer.duration+.005||end-start<.02||end-start>60.005)throw Error('開始と終了の範囲を、0.02〜60秒の長さで指定してください。');return editPCM(Array.from({length:editBuffer.numberOfChannels},(_,i)=>editBuffer.getChannelData(i)),editBuffer.sampleRate,{start,end,normalize:$('soundNormalize').checked,fadeIn:+$('soundFadeIn').value,fadeOut:+$('soundFadeOut').value});}
 $('soundEditPreview').onclick=async()=>{try{stopPreview();const data=edited(),c=await unlockAudio(),b=c.createBuffer(1,data.length,editBuffer.sampleRate);b.copyToChannel(data,0);const source=c.createBufferSource(),gain=c.createGain();source.buffer=b;gain.gain.value=Number($('effectVolume').value)/100;source.connect(gain).connect(c.destination);source.start();editPlay={stop:()=>{try{source.stop();}catch{}source.disconnect();gain.disconnect();}};}catch(e){say(e.message);}};
 $('soundEditSave').onclick=async()=>{const button=$('soundEditSave');button.disabled=true;try{const data=edited(),id=await audio.addPCM($('soundName').value.trim()||editName,data,editBuffer.sampleRate);draft.sound=id;soundOptions(id);say('編集した音を追加しました。「この絵の設定を保存」で絵に結びつけます。');}catch(e){say(e.message||'音声を保存できませんでした。');}finally{button.disabled=false;}};
 function finishRecording(cancel=false){if(cancel)recordGeneration++;clearTimeout(recordTimer);clearInterval(clockTimer);if(recorder&&recorder.state!=='inactive')recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;recordPending=false;$('recordStart').disabled=false;$('recordStop').disabled=true;}
 $('recordStart').onclick=async()=>{if(recorder?.state==='recording'||recordPending)return;const gen=++recordGeneration;recordPending=true;$('recordStart').disabled=true;stopPreview();audio.stopAll();try{if(!navigator.mediaDevices?.getUserMedia||!globalThis.MediaRecorder)throw Error('このブラウザでは録音できません。音声ファイルの取り込みを使ってください。');const incoming=await navigator.mediaDevices.getUserMedia({audio:true});if(gen!==recordGeneration||!$('effectDialog').open){incoming.getTracks().forEach(t=>t.stop());return;}stream=incoming;const mime=['audio/mp4','audio/webm;codecs=opus','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t)),chunks=[];recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});const recorded=recorder;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=async()=>{if(gen!==recordGeneration)return;try{await importBlob(new Blob(chunks,{type:recorded.mimeType}),'録音した音',()=>gen===recordGeneration);if(gen!==recordGeneration)return;$('recordState').textContent='録音終了。使う範囲を編集できます。';}catch(e){say(e.message);}};recorder.start(250);recordStarted=Date.now();$('recordStop').disabled=false;$('recordState').textContent='録音中 0秒';clockTimer=setInterval(()=>{$('recordState').textContent=`録音中 ${Math.floor((Date.now()-recordStarted)/1000)}秒 / 最大60秒`;},500);recordTimer=setTimeout(()=>finishRecording(),60000);}catch(e){if(gen!==recordGeneration)return;finishRecording(true);say(e.name==='NotAllowedError'?'マイクを利用できませんでした。端末のマイク許可を確認するか、音声ファイルを選んでください。':e.message||'録音を開始できませんでした。');}finally{if(gen===recordGeneration){recordPending=false;if(recorder?.state!=='recording')$('recordStart').disabled=false;}}};
 $('recordStop').onclick=()=>finishRecording();
 $('openSoundStudio').onclick=()=>{finishRecording(true);stopPreview();audio.stopAll();if(!$('studioFrame').getAttribute('src'))$('studioFrame').src='sfx_vibe_forge_studio.html';$('studioDialog').showModal();$('studioFrame').contentWindow?.postMessage({type:'kotoba-town-open'},location.origin);};
 $('studioClose').onclick=()=>{$('studioDialog').close();};$('studioDialog').addEventListener('close',()=>{$('studioFrame').contentWindow?.postMessage({type:'kotoba-town-stop'},location.origin);});
 window.addEventListener('message',async e=>{if(e.origin!==location.origin||e.source!==$('studioFrame').contentWindow)return;if(e.data?.type==='kotoba-town-close-studio'){$('studioDialog').close();return;}if(e.data?.type!=='kotoba-town-sfx'||!(e.data.blob instanceof Blob))return;try{await importBlob(e.data.blob,e.data.name||'工房で作った音');if(editBuffer.duration>60)throw Error('工房の音は60秒以内にしてください。');const samples=editPCM(Array.from({length:editBuffer.numberOfChannels},(_,i)=>editBuffer.getChannelData(i)),editBuffer.sampleRate),id=await audio.addPCM(e.data.name||'工房で作った音',samples,editBuffer.sampleRate);draft.sound=id;soundOptions(id);$('studioDialog').close();say('工房で作った音を追加しました。試聴して「この絵の設定を保存」を押してください。');e.source.postMessage({type:'kotoba-town-sfx-saved'},location.origin);}catch(err){say(err.message||'工房の音を追加できませんでした。');$('studioDialog').close();}});
 $('effectDialog').addEventListener('close',()=>{stopPreview();audio.stopAll();finishRecording(true);editBuffer=null;$('effectEditor').hidden=true;});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPreview();audio.stopAll();finishRecording(true);$('studioFrame').contentWindow?.postMessage({type:'kotoba-town-stop'},location.origin);}else if($('studioDialog').open)$('studioFrame').contentWindow?.postMessage({type:'kotoba-town-open'},location.origin);});
 return {get,open,audio,stopAll:()=>{audio.stopAll();stopPreview();},setEnabled:audio.setEnabled,playFor(key,word,duration){const c=get(word);return audio.play(key,c.sound,{loop:c.playMode==='loop'&&duration>0,volume:c.volume});}};
}
